// C# .NET 8 IHttpClientFactory & Polly v8 Integration Template
services.AddHttpClient("AiServiceClient", (sp, client) =>
{
    var config = sp.GetRequiredService<IConfiguration>();
    client.BaseAddress = new Uri(config["Services:AiService:BaseUrl"] ?? "https://ai-service.internal:5001");
    client.Timeout = TimeSpan.FromSeconds(30);
    client.DefaultRequestHeaders.Add("X-Client-Service", "EnterpriseApi-Gateway");
})
.AddHttpMessageHandler<BearerTokenPropagationDelegatingHandler>()
.AddHttpMessageHandler<TenantHeaderPropagationDelegatingHandler>()
.AddHttpMessageHandler<CorrelationIdDelegatingHandler>()
.ConfigurePrimaryHttpMessageHandler(() =>
{
    var handler = new SocketsHttpHandler
    {
        PooledConnectionLifetime = TimeSpan.FromMinutes(15),
        PooledConnectionIdleTimeout = TimeSpan.FromMinutes(2),
        MaxConnectionsPerServer = 200,
        EnableMultipleHttp2Connections = true
    };
    return handler;
})
.AddStandardResilienceHandler(options =>
{
    options.Retry.MaxRetryAttempts = 3;
    options.Retry.BackoffType = DelayBackoffType.Exponential;
    options.CircuitBreaker.SamplingDuration = TimeSpan.FromSeconds(30);
    options.CircuitBreaker.FailureRatio = 0.5;
    options.CircuitBreaker.BreakDuration = TimeSpan.FromSeconds(15);
    options.TotalRequestTimeout.Timeout = TimeSpan.FromSeconds(30);
});
